#include <vector>
#include <omp.h>

double productWithInverses(std::vector<double> const& x) {
    const std::size_t n = x.size();
    double prod = 1.0;

    #pragma omp parallel for reduction(*:prod)
    for (std::size_t i = 0; i < n; ++i) {
        const double v = x[i];
        if ((i & 1u) == 0u) {
            prod *= v;        // even index: multiply by x[i]
        } else {
            prod *= 1.0 / v;  // odd index: multiply by inverse
        }
    }

    return prod;
}
