#include <vector>
#include <cstddef>
#include <omp.h>

double productWithInverses(std::vector<double> const& x) {
    const std::size_t n = x.size();
    if (n == 0) return 1.0;

    // Deterministic, order-independent approach:
    // accumulate in log-domain with a fixed reduction over threads.
    // This avoids non-associativity/order dependence of floating-point multiplication.
    int nt = 1;
    #pragma omp parallel
    {
        #pragma omp single
        nt = omp_get_num_threads();
    }

    std::vector<long double> partial(nt, 0.0L);

    #pragma omp parallel
    {
        const int tid = omp_get_thread_num();
        long double local = 0.0L;

        #pragma omp for schedule(static)
        for (std::size_t i = 0; i < n; ++i) {
            long double v = static_cast<long double>(x[i]);
            // Assume inputs are valid for inversion/log (no zeros/negatives).
            if ((i & 1u) == 0u) local += logl(v);
            else                local -= logl(v);
        }

        partial[tid] = local; // single writer per element => no race
    }

    long double sum = 0.0L;
    for (int t = 0; t < nt; ++t) sum += partial[t];

    return static_cast<double>(expl(sum));
}
